(()=>{function refresh(){const get=id=>Number((document.getElementById(id)?.textContent||'').replace(/,/g,'').match(/[0-9]+(?:\.[0-9]+)?/)?.[0]||0);const money=v=>'€'+new Intl.NumberFormat('en-IE',{maximumFractionDigits:0}).format(v);const qty=v=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:1}).format(v);const disposal=Number((document.querySelector('[data-disposal-saving]')?.textContent||'').replace(/[^0-9.]/g,''));const vals={baseline:money(get('calc-solvent-baseline')*3),baselineLitres:qty(get('bc-baseline-litres')*3)+' L',litres:qty(get('calc-annual-litres')*3)+' L',material:money(get('calc-annual-saving')*3),disposal:money(disposal*3),carbon:(()=>{const n=id=>Number(document.getElementById(id).value)||0;const v=n('calc-labs')*n('calc-hplc-count')*n('calc-flow')*60*n('calc-hours-day')*n('calc-days-week')*n('calc-weeks-year')/1000;return new Intl.NumberFormat('en-IE',{maximumFractionDigits:2}).format(v*(n('calc-recovery')/100*3.69+n('calc-waste-reduction')/100*1.57)*3/1000)+' t CO₂e'})()};document.querySelectorAll('[data-financial-project]').forEach(e=>e.textContent=vals[e.dataset.financialProject]);}document.addEventListener('resolve-model',()=>requestAnimationFrame(refresh));refresh();})();